"""Render the completed aggregate audit as a standalone HTML report and PNG."""
import base64
import csv
import html
import json
from collections import Counter, defaultdict
from pathlib import Path

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT = Path(__file__).resolve().parent
DEST = ROOT / 'data' / 'reports'
p = json.loads((DEST / 'current_dataset_profile.json').read_text())
assert p.get('complete'), 'Run profile_current_datasets.py to completion first.'
m, r, i, c = [p[k] for k in ('google_metadata','google_core_reviews','inspections','inspection_candidates')]

# Recompute the supplemental inspection diagnostics from the raw CSV.
s = {'core_blank_violations_by_result':Counter(), 'core_inspection_date_bands':Counter(),
     'violation_1_titles_by_period':defaultdict(Counter), 'core_coordinate_flags':Counter()}
with (ROOT / 'Food_Inspections_20261103.csv').open(encoding='utf-8-sig', newline='') as f:
    for row in csv.DictReader(f):
        if (row['City'].strip().upper(),row['State'].strip().upper(),row['Facility Type'].strip().upper()) != ('CHICAGO','IL','RESTAURANT'):
            continue
        month,day,year = row['Inspection Date'].split('/')
        date = f'{year}-{month}-{day}'
        s['core_inspection_date_bands']['2010_to_2021_09_08' if date <= '2021-09-08' else 'after_2021_09_08'] += 1
        if not row['Violations']: s['core_blank_violations_by_result'][row['Results']] += 1
        if row['Latitude'] and row['Longitude']:
            lat,lon=float(row['Latitude']),float(row['Longitude'])
            s['core_coordinate_flags']['outside_broad_chicago_rectangle'] += not (41.64<=lat<=42.03 and -87.94<=lon<=-87.52)
        for v in row['Violations'].split('|'):
            if v.strip().startswith('1. '):
                s['violation_1_titles_by_period']['before_2018' if year<'2018' else '2018_onward'][v.strip().split(' - Comments:')[0]] += 1
(DEST / 'supplemental_inspection_profile.json').write_text(json.dumps(s,indent=2)+'\n')

def n(v): return f'{v:,}'
def pct(a,b): return f'{100*a/b:.1f}%'
def esc(v): return html.escape(str(v))
def table(headers, rows):
    return '<table><thead><tr>'+''.join(f'<th>{esc(v)}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def para(text): return '<p>'+text+'</p>'
def section(title,content): return '<section><h2>'+esc(title)+'</h2>'+content+'</section>'
def rate(results): return 100*results.get('Fail',0)/sum(results.get(k,0) for k in ('Pass','Pass w/ Conditions','Fail'))

plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False})
fig, axs = plt.subplots(2,2,figsize=(14,10),layout='constrained')
years=list(range(2010,2027))
axs[0,0].bar(years,[i['core_years'].get(str(y),0) for y in years],color='#187f8e')
axs[0,0].axvline(2021.69,color='#af3c34',linestyle='--',label='Statewide Google reviews end Sep 2021')
axs[0,0].set(title='Chicago restaurant inspection events',ylabel='Events',xlabel='Year (2026 is partial)')
axs[0,0].set_xticks(range(2010,2027,2))
axs[0,0].legend(fontsize=8)
ry=sorted(int(y) for y in r['unique_years_utc'] if int(y)>=2010)
axs[0,1].bar(ry,[r['unique_years_utc'][str(y)] for y in ry],color='#5773ac')
axs[0,1].set(title='Restaurant Google reviews\nAfter exact deduplication',ylabel='Reviews',xlabel='UTC year (2021 is partial)')
axs[0,1].ticklabel_format(axis='y',style='plain')
types=['Canvass','Canvass Re-Inspection','Complaint','Complaint Re-Inspection','License']
vals=[rate(i['core_type_results'][t]) for t in types]
axs[1,0].barh(types,vals,color='#bb7441')
axs[1,0].set(title='Failure share differs by inspection type',xlabel='Fail / (Pass + Conditional + Fail), %')
for j,v in enumerate(vals): axs[1,0].text(v+.3,j,f'{v:.1f}%',va='center')
axs[1,0].set_xlim(0,max(vals)*1.23)
labels=['Google core places','Address candidate','Address + name candidate','One valid license among name candidates']
counts=[m['core_restaurants'],c['core']['same_address'],c['core']['same_address_exact_name'],c['core']['exact_name_one_valid_license']]
axs[1,1].barh(labels,counts,color='#527d65')
axs[1,1].invert_yaxis()
axs[1,1].set(title='Business-link candidates\nNo links have been verified',xlabel='Google places')
for j,v in enumerate(counts): axs[1,1].text(v+65,j,n(v),va='center')
axs[1,1].set_xlim(0,max(counts)*1.2)
fig.savefig(DEST / 'dataset_overview.png',dpi=170)
plt.close(fig)
img=base64.b64encode((DEST / 'dataset_overview.png').read_bytes()).decode()

parts=[para('<strong>The usable primary combination is Google reviews plus Chicago food inspections. The local Yelp files contain no eligible Chicago restaurants.</strong> The sources support historical restaurant analysis after deduplication and business-link verification. They do not yet form a validated modeling dataset.'),
       para('Audit date: November 22, 2026. Every raw file was scanned in full. Raw inputs and the existing notebook were left unchanged. File sizes below use decimal GB/MB; dates describe observations, not download or snapshot dates.')]
mapping=[('meta-Illinois.json','google_metadata','Place metadata; duplicate gmap_id rows'),('review-Illinois.json','google_reviews','Google rating/review record'),
         ('Food_Inspections_20261103.csv','inspections','Inspection event'),('yelp_academic_dataset_business.json','yelp_business','Yelp business'),
         ('yelp_academic_dataset_review.json','yelp_review','Yelp review'),('yelp_academic_dataset_tip.json','yelp_tip','Tip, not a rated review'),
         ('yelp_academic_dataset_checkin.json','yelp_checkin','Business with timestamp list'),('yelp_academic_dataset_user.json','yelp_user','User snapshot')]
parts.append(section('Inventory', table(['File','Rows','Size, GB','Grain'],[(fn,n(p[key]['rows']),f"{p['files'][fn]['bytes']/1e9:.3f}",grain) for fn,key,grain in mapping])+para(f"Total size: {sum(v['bytes'] for v in p['files'].values())/1e9:.2f} GB. All JSON inputs are JSON Lines. All JSON records parsed successfully; the CSV scan completed with unique Inspection IDs.")))
parts.append('<img alt="Dataset coverage and inspection diagnostics" src="data:image/png;base64,'+img+'">')
parts.append(section('Fields, keys, and relationships',table(['Source','Key / relationship','Main analytical fields'],[
    ('Google metadata','gmap_id; deduplicate before joining','name, address, latitude/longitude, category list, avg_rating, num_of_reviews, hours, price, operating state'),
    ('Google reviews','gmap_id references metadata; no native review ID','user_id, time in milliseconds, rating, text, reviewer name, pics, owner response'),
    ('Inspections','Inspection ID identifies an event; License # is not a stable restaurant identity','DBA/AKA names, address, date, facility type, risk, inspection type, result, violations, coordinates'),
    ('Yelp business','business_id','city/state, coordinates, categories, stars, review_count, hours, attributes, is_open'),
    ('Yelp reviews','review_id; business_id and user_id references','stars, text, date, useful/funny/cool vote counts'),
    ('Yelp tips','business_id and user_id; no native tip ID','text, date, compliment_count'),
    ('Yelp check-ins','business_id; comma-separated date list','Each timestamp represents an event, not an identified person'),
    ('Yelp users','user_id','Account creation date, review_count, average_stars, friends, elite, fans, compliments')
])+para('Within-platform place-to-review joins are many-to-one after place-key deduplication. Google user IDs and Yelp user IDs are unrelated. Google review name identifies the reviewer, not the restaurant. No Google/Yelp identifier directly equals an inspection license. Nested metadata and encoded lists require explicit parsing rather than treating their display strings as scalar categories.')))
parts.append(section('Google place scope and quality',para(f"The metadata has {n(m['rows'])} rows and {n(m['unique_ids'])} unique places. All {n(m['duplicate_id_extra_rows'])} extra rows duplicate the first full record for their ID; no conflicts were found. Address-based selection finds {n(m['chicago_places'])} Chicago places, of which {n(m['core_restaurants'])} meet the documented restaurant rule. Another {n(m['cafe_cafeteria_expansion'])} cafe/cafeteria places form a separate possible expansion. The older pizza-only definition finds {n(m['chicago_pizza_places'])} places.")+para('Core categories include Restaurant, categories ending in restaurant, Bar & grill, Diner, Sandwich shop, Bistro, and Crêperie. Category matching is case/accent/whitespace normalized. Restaurant supply stores do not qualify. A pizza delivery/takeaway-only category can be outside this restaurant definition, so the pizza cohort is not strictly nested within the core cohort. Geography uses Chicago/IL address text; no official boundary polygon was available.')+para(f"Of core restaurants, {n(m['core_permanently_closed'])} ({pct(m['core_permanently_closed'],m['core_restaurants'])}) are marked permanently closed in the undated metadata. Preserve them for historical work. Metadata state is operating status, not geographic state. Median snapshot rating is {m['core_snapshot_rating_distribution']['median']:.1f}; mean place-level snapshot rating is {m['core_snapshot_rating_distribution']['mean']:.2f}. These are undated summaries, not historical predictors.")+table(['Missing core field','Places','Share'],[(k,n(v),pct(v,m['core_restaurants'])) for k,v in sorted(m['core_missing'].items(),key=lambda x:-x[1])])+para('Across statewide metadata, 2,163 addresses and 719 category lists are missing. A strict city/category filter cannot establish eligibility for those records. All core records have the core identity, coordinate, rating, and review-count fields populated; populated does not establish correctness.')))
parts.append(section('Google review quality and analytical coverage',para(f"Statewide reviews total {n(p['google_reviews']['rows'])}; all reference metadata IDs, and every metadata place has at least one review record. The overall UTC range is {p['google_reviews']['time_min_utc']} through {p['google_reviews']['time_max_utc']}. The core restaurant range is {r['time_min_utc']} through {r['time_max_utc']}.")+table(['Core review measure','Count'],[(key,n(r[key])) for key in ('raw_rows','unique_rows','duplicate_extra_rows','identity_conflicting_extra_rows','places_with_reviews','places_without_reviews')])+para(f"Exact full-record deduplication removes {pct(r['duplicate_extra_rows'],r['raw_rows'])} of core rows. Remaining conflicting user/place/time records need adjudication; they are counted, not silently resolved. There are {n(r['unique_missing'].get('text',0))} reviews without text ({pct(r['unique_missing'].get('text',0),r['unique_rows'])}) and {n(r['unique_missing'].get('rating',0))} without a rating. Valid ratings with text total {n(r['flags']['valid_rating_with_text_rows'])}; sentiment and rating analysis therefore have different eligible denominators.")+table(['Rating','Deduplicated core records'],[(k,n(v)) for k,v in sorted(r['unique_ratings'].items())])+para(f"The valid-review-weighted mean is {r['review_weighted_mean_rating']:.3f}. Review volume is skewed: median {r['per_place_review_counts']['median']:.0f}, 90th percentile {r['per_place_review_counts']['p90']}, maximum {n(r['per_place_review_counts']['max'])}; {n(r['places_under_10_reviews'])} places have fewer than 10 reviews. The top 1% of places by review volume account for {100*r['top_1pct_places_share_of_reviews']:.1f}% of reviews. Review-weighted results overrepresent popular places.")+para(f"There are {n(r['flags']['pre_2010_rows'])} core records dated before 2010, including implausible early timestamps. A parseable timestamp is not proof of a valid observation date. Metadata review counts equal deduplicated exports at {n(r['export_vs_metadata'].get('equal',0))} places, exceed exports at {n(r['export_vs_metadata'].get('below',0))}, and fall below exports at {n(r['export_vs_metadata'].get('above',0))}. The export and metadata should not be assumed to represent the same snapshot.")+table(['UTC year','Deduplicated core reviews'],[(y,n(v)) for y,v in sorted(r['unique_years_utc'].items())])))
parts.append(section('Inspection events, outcomes, and consistency',para(f"The CSV has {n(i['rows'])} unique inspection events from {i['date_min']} through {i['date_max']}. Normalizing city/state retains {n(i['chicago_rows'])} Chicago events. Requiring Facility Type = Restaurant leaves {n(i['core_rows'])} events, {n(i['core_unique_valid_licenses'])} distinct valid licenses, and {n(i['core_unique_normalized_addresses'])} normalized addresses. These are not counts of verified restaurants: licenses and operators change over time. Mixed facility labels and missing facility types require a separate scope review.")+table(['Result','Core events','Share of all core events'],[(k,n(v),pct(v,i['core_rows'])) for k,v in sorted(i['core_results'].items(),key=lambda x:-x[1])])+para(f"The event failure share is {rate(i['core_results']):.2f}% among Pass, Pass w/ Conditions, and Fail only. It is {pct(i['core_results']['Fail'],i['core_rows'])} of all core events; those denominators answer different questions. No Entry, Not Ready, Out of Business, and Business Not Located are not passes. Conditional passes should remain distinct.")+table(['Inspection type','Eligible-result failure share'],[(t,f"{rate(i['core_type_results'][t]):.2f}%") for t in types])+para(f"Missing violation text occurs in {n(i['core_missing']['Violations'])} events, including {n(s['core_blank_violations_by_result']['Fail'])} failures. It cannot be interpreted as no violations. Core missing values include {n(i['core_missing']['License #'])} invalid/missing licenses, {n(i['core_missing']['Latitude'])} coordinate pairs, and {n(i['core_missing']['AKA Name'])} aliases. Risk 1 (High) accounts for {pct(i['core_risks']['Risk 1 (High)'],i['core_rows'])} of restaurant events; risk classification and inspection outcome are different variables.")+para('Violation code meanings shift in the files. Code 1 describes food sourcing in pre-2018 records but usually person-in-charge duties in 2018 onward. Preserve the title and inspection date when parsing codes; do not assume a numeric code has one stable meaning. Inspection-type spelling variants and unusual free-text labels also need normalization. A broad coordinate rectangle found no core coordinate outliers, but this is not a boundary or business-location validation.')+table(['Year','Core events','Failure share among eligible outcomes'],[(y,n(v),f"{rate(i['core_year_results'][y]):.2f}%") for y,v in sorted(i['core_years'].items())])+para('2026 is partial. Outcome proportions, inspection mix, restaurant turnover, and recording practices change over time; year-to-year rates do not by themselves establish a change in hygiene.')))
parts.append(section('Yelp: substantial volume, no Chicago cohort',para(f"There are {n(p['yelp_business']['rows'])} Yelp businesses, {n(p['yelp_business']['illinois_businesses'])} in Illinois, and {n(p['yelp_business']['flags']['illinois_restaurants'])} Illinois restaurants. The normalized Chicago + IL + Restaurants filter yields {n(p['yelp_business']['eligible_chicago_restaurants'])} businesses. The broad Chicago coordinate rectangle contains {len(p['yelp_business']['near_chicago_records'])} business records. This coordinate screen checks obvious locality errors, not precise city membership.")+table(['Chicago city-label record','State','Latitude','Longitude','Categories'],[(v['name'],v['state'],v['latitude'],v['longitude'],v['categories']) for v in p['yelp_business']['chicago_city_records']])+table(['Dataset','Date meaning','Minimum','Maximum','Missing business references'],[(k,'Account creation' if k=='user' else 'Check-in event' if k=='checkin' else 'Record timestamp',p['yelp_'+k]['date_min'],p['yelp_'+k]['date_max'],p['yelp_'+k]['flags'].get('business_id_absent_from_business_file','N/A')) for k in ('review','tip','checkin','user')])+para(f"The check-in file encodes {n(p['yelp_checkin']['flags']['checkin_events'])} events inside {n(p['yelp_checkin']['rows'])} rows; row count is not visit count. Tips have no star rating. User review_count, average_stars, friends, and elite fields are snapshots and must not be treated as historically available features. Yelp review/user/full-record uniqueness and user foreign keys were not tested. Business foreign keys in reviews, tips, and check-ins were checked.")+para('The five Yelp files were fully scanned for this inventory. Their dependent records add no eligible Chicago restaurant rows under this definition. They could support a separate geographic study, but combining statewide Illinois Yelp businesses with Chicago Google/inspection data would change the target population.')))
parts.append(section('Business matching and temporal alignment',table(['Core place candidate measure','Places','Share of core'],[(k,n(v),pct(v,m['core_restaurants'])) for k,v in c['core'].items()])+para(f"These are overlapping candidate diagnostics, not accepted links. There are {n(i['chicago_license_address_groups_multiple_names'])} Chicago license/address groups with multiple normalized DBA names and {n(i['chicago_licenses_multiple_addresses'])} licenses at multiple normalized addresses. {n(c['core']['exact_name_nearest_over_100m'])} exact address/name candidates have their nearest matching inspection coordinate more than 100 meters away. Tenant units, shared buildings, chain branches, ownership changes, and historical aliases require review.")+para(f"Only {n(r['flags']['reviews_on_or_after_first_exact_candidate_inspection'])} deduplicated core reviews are on or after the first inspection of an exact-name/address candidate. This is a rough temporal diagnostic, not accepted linkage or proof of a prior inspection: it uses UTC dates and includes same-day records. {n(s['core_inspection_date_bands']['after_2021_09_08'])} core inspections occur after the final statewide Google review date. They cannot be inspections preceding the reviews.")+para('Keep source tables at their natural grains: one place, one review, one inspection. Build a reviewed source-place → restaurant episode → license crosswalk with evidence, confidence, decision, and supported dates. Do not join every review to every inspection, and do not join solely on address or license. For inspection prediction, use one row per eligible inspection with review features strictly before that inspection, a predefined lookback window, and Chicago local-date alignment. For retrospective comparisons, use restaurant-month aggregates with the latest accepted prior inspection.')))
parts.append(section('Readiness, limitations, and next work',para('The repository currently contains raw sources, a preliminary profiler, a merge plan, and an exploratory notebook. No accepted business crosswalk or completed analytical table was present. The notebook reads only 1,000 metadata rows, while its Google review read has no row/chunk limit despite the preview comment. The saved code has no unfinished metadata.category.n expression and no saved errors; the merge plan’s notebook note is partly stale.')+para('Recommended sequence: freeze restaurant/geography rules; deduplicate places and retained reviews; quarantine invalid dates and conflicting identities; build and manually validate business-episode links; export scoped unmatched tables as well as the accepted matched subset; then construct time-safe features. Evaluate chronological holdouts and restaurant-group leakage, compare against inspection-history baselines, and stratify performance by inspection type, time period, review volume, and matched/unmatched coverage.')+para('No correlation, causal effect, predictive accuracy, sentiment score, or accepted restaurant match rate is asserted by this audit. Missing or conflicting reviews, unresolved historical identities, undated metadata, platform selection, popularity skew, code-definition changes, and review-era coverage limit those conclusions. Full scans establish the counts shown; they do not establish provenance, completeness of either platform, or that the cohort is a census of Chicago restaurants.')+para('Reproduce: run <code>python -u profile_current_datasets.py</code>, then <code>python build_dataset_report.py</code>. The first script uses only the Python standard library and local normalization helpers; rendering requires matplotlib. Detailed aggregates and field schemas are in <code>current_dataset_profile.json</code>; supplemental inspection checks are in <code>supplemental_inspection_profile.json</code>.')))

document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ChicagoPizza514 dataset analysis — November 22, 2026</title><style>body{font:16px/1.65 system-ui,sans-serif;max-width:1150px;margin:40px auto;padding:0 25px;color:#23333d;background:#fafbf9}h1{font-size:32px}h2{font-size:23px;color:#126371;margin-top:40px}table{border-collapse:collapse;width:100%;font-size:14px;margin:20px 0;overflow-wrap:anywhere}th,td{padding:9px 12px;text-align:left;border-bottom:1px solid #d7dfdf;vertical-align:top}th{background:#e9efed}tr:nth-child(even){background:#f1f5f3}img{width:100%;margin:24px 0}code{background:#e9efed;padding:2px 5px}section{break-inside:auto}@media print{body{max-width:none;margin:0;font-size:11px}h2{break-after:avoid}table{font-size:10px}}</style><h1>ChicagoPizza514: analysis of the current datasets</h1>'''+''.join(parts)+'</html>'
(DEST / 'dataset_analysis.html').write_text(document,encoding='utf-8')
print(DEST / 'dataset_analysis.html')
